BEGIN;

DO $$
DECLARE
  hw_id uuid;
  legacy_hardware_id uuid;
  rd_id uuid;
  embedded_software_id uuid;
  software_id uuid;
  production_id uuid;
  engineering_production_id uuid;
  system_administrator_id uuid;
  unresolved_count bigint;
BEGIN
  SELECT id INTO hw_id FROM public.departments WHERE code = 'HW' AND is_active LIMIT 1;
  SELECT id INTO legacy_hardware_id FROM public.departments WHERE lower(name) = 'hardware' AND id <> hw_id LIMIT 1;
  SELECT id INTO rd_id FROM public.departments WHERE code = 'R&D' LIMIT 1;
  SELECT id INTO embedded_software_id FROM public.departments WHERE code = 'ESW' LIMIT 1;
  SELECT id INTO software_id FROM public.departments WHERE code = 'SW' LIMIT 1;
  SELECT id INTO production_id FROM public.departments WHERE code = 'MPRD/PRD-01' LIMIT 1;
  SELECT id INTO engineering_production_id FROM public.departments WHERE code = 'EPRD/PRD-02' LIMIT 1;
  SELECT id INTO system_administrator_id FROM public.employees WHERE display_name = 'System Administrator' LIMIT 1;
  IF hw_id IS NULL OR legacy_hardware_id IS NULL OR rd_id IS NULL OR embedded_software_id IS NULL OR software_id IS NULL OR production_id IS NULL OR engineering_production_id IS NULL OR system_administrator_id IS NULL THEN RAISE EXCEPTION 'Approved access redesign prerequisites are missing.'; END IF;
  INSERT INTO public.employee_departments (employee_id, department_id, is_primary) SELECT employee_id, hw_id, is_primary FROM public.employee_departments WHERE department_id = legacy_hardware_id ON CONFLICT (employee_id, department_id) DO UPDATE SET is_primary = public.employee_departments.is_primary OR EXCLUDED.is_primary;
  DELETE FROM public.employee_departments WHERE department_id = legacy_hardware_id;
  UPDATE public.employees SET primary_department_id = hw_id WHERE primary_department_id = legacy_hardware_id;
  UPDATE public.departments SET parent_department_id = hw_id WHERE parent_department_id = legacy_hardware_id;
  UPDATE public.hr_job_postings SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.hr_job_profiles SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.hr_job_requisitions SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.hr_onboarding_plans SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.hr_training_programs SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.project_tasks SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.purchase_requests SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.qms_audits SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.qms_kpis SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.qms_quality_objectives SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.qms_risks SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.quick_expenses SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.rd_members SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  UPDATE public.requirement_feasibility_reviews SET department_id = hw_id WHERE department_id = legacy_hardware_id;
  SELECT ((SELECT count(*) FROM public.employee_departments WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.employees WHERE primary_department_id = legacy_hardware_id) + (SELECT count(*) FROM public.departments WHERE parent_department_id = legacy_hardware_id) + (SELECT count(*) FROM public.hr_job_postings WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.hr_job_profiles WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.hr_job_requisitions WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.hr_onboarding_plans WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.hr_training_programs WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.project_tasks WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.purchase_requests WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.qms_audits WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.qms_kpis WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.qms_quality_objectives WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.qms_risks WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.quick_expenses WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.rd_members WHERE department_id = legacy_hardware_id) + (SELECT count(*) FROM public.requirement_feasibility_reviews WHERE department_id = legacy_hardware_id)) INTO unresolved_count;
  IF unresolved_count <> 0 THEN RAISE EXCEPTION 'Legacy Hardware references remain: %', unresolved_count; END IF;
  UPDATE public.departments SET parent_department_id = rd_id WHERE id IN (hw_id, embedded_software_id, software_id);
  UPDATE public.departments SET parent_department_id = production_id WHERE id = engineering_production_id;
  UPDATE public.employees SET primary_department_id = rd_id WHERE id = system_administrator_id;
  INSERT INTO public.employee_departments (employee_id, department_id, is_primary) VALUES (system_administrator_id, rd_id, true) ON CONFLICT (employee_id, department_id) DO UPDATE SET is_primary = true;
  UPDATE public.employee_departments SET is_primary = false WHERE employee_id = system_administrator_id AND department_id <> rd_id;
  UPDATE public.departments SET name = 'Hardware (Legacy Alias)', code = NULL, description = coalesce(description || E'\n\n', '') || 'Legacy alias migrated to canonical HW department.', is_active = false, parent_department_id = rd_id WHERE id = legacy_hardware_id;
END $$;

INSERT INTO public.permissions (key, module_key, label, description) VALUES ('inventory.view', 'inventory', 'View inventory', 'Allows read-only access to approved inventory records.'), ('inventory.manage', 'inventory', 'Manage inventory', 'Allows controlled inventory management through existing protected workflows.') ON CONFLICT (key) DO NOTHING;
WITH role_permissions(role_name, permission_key) AS (VALUES ('Employee / Engineer', 'engineering.view'), ('Employee / Engineer', 'engineering.create'), ('Employee / Engineer', 'engineering.edit'), ('Employee / Engineer', 'projects.view'), ('Employee / Engineer', 'documents.view'), ('Employee / Engineer', 'inventory.view'), ('Project Manager', 'engineering.view'), ('Project Manager', 'engineering.create'), ('Project Manager', 'engineering.edit'), ('Project Manager', 'projects.view'), ('Project Manager', 'projects.create'), ('Project Manager', 'projects.edit'), ('Project Manager', 'documents.view'), ('Project Manager', 'documents.create'), ('Project Manager', 'documents.edit'), ('Project Manager', 'inventory.view'), ('Team Lead', 'engineering.view'), ('Team Lead', 'engineering.create'), ('Team Lead', 'engineering.edit'), ('Team Lead', 'projects.view'), ('Team Lead', 'projects.create'), ('Team Lead', 'projects.edit'), ('Team Lead', 'documents.view'), ('Team Lead', 'documents.create'), ('Team Lead', 'documents.edit'), ('Team Lead', 'inventory.view'), ('Team Lead', 'procurement.view'), ('Team Lead', 'procurement.create'), ('Team Lead', 'procurement.edit'), ('Team Lead', 'production.view'), ('Team Lead', 'quality.view'), ('Team Lead', 'qms.view'), ('Purchase', 'procurement.view'), ('Purchase', 'procurement.create'), ('Purchase', 'procurement.edit'), ('Purchase', 'procurement.approve'), ('Purchase', 'inventory.view'), ('Storekeeper', 'inventory.view'), ('Storekeeper', 'inventory.manage'), ('Storekeeper', 'procurement.view'), ('Storekeeper', 'procurement.edit'), ('Sales', 'sales.view'), ('Sales', 'sales.create'), ('Sales', 'sales.edit'), ('Sales', 'projects.view'), ('Sales', 'documents.view'), ('HR Admin', 'hr.view'), ('HR Admin', 'recruitment.manage'), ('HR Admin', 'leave.manage'), ('HR Admin', 'leave.approve'), ('HR Admin', 'training.manage'), ('Production Manager / Operator', 'production.view'), ('Production Manager / Operator', 'production.create'), ('Production Manager / Operator', 'production.edit'), ('Production Manager / Operator', 'inventory.view'), ('QA', 'quality.view'), ('QA', 'quality.create'), ('QA', 'quality.edit'), ('QA', 'qms.view'), ('QA', 'inventory.view'), ('Security', 'security.view'), ('Security', 'security.create'), ('Security', 'security.edit'), ('Facility', 'facility.view'), ('Facility', 'facility.create'), ('Facility', 'facility.edit'), ('Maintenance', 'maintenance.view'), ('Maintenance', 'maintenance.create'), ('Maintenance', 'maintenance.edit'), ('Asset Manager', 'assets.view'), ('Asset Manager', 'assets.create'), ('Asset Manager', 'assets.edit'), ('Finance', 'finance.view'), ('Finance', 'finance.create'), ('Finance', 'finance.edit'), ('QMS Manager', 'qms.view'), ('QMS Manager', 'qms.create'), ('QMS Manager', 'qms.edit'), ('QMS Manager', 'qms.approve'), ('Viewer / Auditor', 'documents.view'), ('Viewer / Auditor', 'projects.view'), ('Viewer / Auditor', 'qms.view'), ('Calibration', 'calibration.view'), ('Calibration', 'calibration.create'), ('Calibration', 'calibration.edit'), ('Head of Department', 'projects.view'), ('Head of Department', 'projects.edit'), ('Head of Department', 'documents.view'), ('Head of Department', 'documents.edit'), ('Head of Department', 'procurement.view'), ('Head of Department', 'procurement.approve'), ('Head of Department', 'inventory.view'), ('Head of Department', 'production.view'), ('Head of Department', 'quality.view'), ('Head of Department', 'qms.view')) INSERT INTO public.access_role_permissions (role_id, permission_id) SELECT r.id, p.id FROM role_permissions rp JOIN public.access_roles r ON r.name = rp.role_name JOIN public.permissions p ON p.key = rp.permission_key ON CONFLICT (role_id, permission_id) DO NOTHING;
UPDATE public.employees e SET default_role_id = ear.role_id FROM public.employee_access_roles ear WHERE ear.employee_id = e.id AND e.default_role_id IS DISTINCT FROM ear.role_id AND NOT EXISTS (SELECT 1 FROM public.employee_access_roles other WHERE other.employee_id = e.id AND other.role_id <> ear.role_id);
CREATE OR REPLACE FUNCTION public.has_any_permission(_user_id uuid, _permission_keys text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id, 'admin'::public.app_role) OR EXISTS (SELECT 1 FROM public.employee_access_roles ear JOIN public.access_role_permissions arp ON arp.role_id = ear.role_id JOIN public.permissions p ON p.id = arp.permission_id JOIN public.employees e ON e.id = ear.employee_id WHERE e.user_id = _user_id AND e.employment_status = 'ACTIVE' AND p.key = ANY(_permission_keys)); $$;
REVOKE ALL ON FUNCTION public.has_any_permission(uuid, text[]) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.has_any_permission(uuid, text[]) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.can_inward(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_uid, 'admin'::public.app_role) OR public.has_permission(_uid, 'inventory.manage'); $$;
REVOKE ALL ON FUNCTION public.can_inward(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.can_inward(uuid) TO authenticated, service_role;
DROP POLICY IF EXISTS "Approved engineering and stores teams view components" ON public.components; CREATE POLICY "Explicit inventory readers view components" ON public.components FOR SELECT TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.view', 'inventory.manage', 'engineering.view', 'engineering.edit', 'procurement.view', 'procurement.edit', 'production.view', 'quality.view']));
DROP POLICY IF EXISTS "Approved engineering and stores teams manage components" ON public.components; CREATE POLICY "Explicit inventory managers manage components" ON public.components FOR ALL TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.manage'])) WITH CHECK (public.has_any_permission(auth.uid(), ARRAY['inventory.manage']));
DROP POLICY IF EXISTS "Approved engineering and stores teams view inventory locations" ON public.locations; CREATE POLICY "Explicit inventory readers view locations" ON public.locations FOR SELECT TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.view', 'inventory.manage', 'engineering.view', 'engineering.edit', 'procurement.view', 'procurement.edit', 'production.view', 'quality.view']));
DROP POLICY IF EXISTS "Approved stores and procurement teams manage inventory locations" ON public.locations; CREATE POLICY "Stores manage inventory locations" ON public.locations FOR ALL TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.manage'])) WITH CHECK (public.has_any_permission(auth.uid(), ARRAY['inventory.manage']));
DROP POLICY IF EXISTS "Approved stores procurement and quality teams view inventory lots" ON public.inventory_lots; CREATE POLICY "Explicit inventory readers view inventory lots" ON public.inventory_lots FOR SELECT TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.view', 'inventory.manage', 'engineering.view', 'engineering.edit', 'procurement.view', 'procurement.edit', 'production.view', 'quality.view']));
DROP POLICY IF EXISTS "Operational teams view substitutes" ON public.component_substitutes; CREATE POLICY "Explicit inventory readers view substitutes" ON public.component_substitutes FOR SELECT TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.view', 'inventory.manage', 'engineering.view', 'engineering.edit', 'procurement.view', 'procurement.edit', 'production.view', 'quality.view']));
DROP POLICY IF EXISTS "Operational teams manage substitutes" ON public.component_substitutes; CREATE POLICY "Stores manage substitutes" ON public.component_substitutes FOR ALL TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.manage'])) WITH CHECK (public.has_any_permission(auth.uid(), ARRAY['inventory.manage']));
DROP POLICY IF EXISTS "Operational teams view component projects" ON public.component_projects; DROP POLICY IF EXISTS "Operational teams manage component_projects" ON public.component_projects; CREATE POLICY "Explicit inventory readers view component projects" ON public.component_projects FOR SELECT TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.view', 'inventory.manage', 'engineering.view', 'engineering.edit', 'procurement.view', 'procurement.edit', 'production.view', 'quality.view'])); CREATE POLICY "Stores manage component projects" ON public.component_projects FOR ALL TO authenticated USING (public.has_any_permission(auth.uid(), ARRAY['inventory.manage'])) WITH CHECK (public.has_any_permission(auth.uid(), ARRAY['inventory.manage']));
COMMIT;